/* diff-ref-struct · the Map viewer's bundle (Plots' step 18, L409): the viewer and the four shell files it leans on
   written as one classic script, so that the page the core writes (`drs plots show`, PL38) carries the app's map and
   not a second one. Pure: the same sources give the same bytes. Used by the node bundler (app/ui/tools/
   bundle-viewer.mjs, which writes core/assets/viewer/) and by the app's Export ▸ Viewer Page… (Dev), which bundles the
   same sources fetched from the app. Each ES module becomes plain script by dropping its `import` lines (every import
   is one of the sources, in order) and the `export` keyword before a declaration; the sources share no top-level
   name (a node test checks). */

/** The sources, in dependency order, by their path under app/ui/. */
export const VIEWER_SOURCES = ["ticks.js", "svgexport.js", "mapclip.js", "plot.js", "viewer/map.js"];

/** One module's text as a plain script: its imports dropped, its exports made plain declarations. Throws on an
    import of anything but a source, or an export this transform does not take. */
export function plainScript(name, text) {
  const out = [];
  for (const line of text.split("\n")) {
    const im = /^import\s+(?:\{[^}]*\}|\*\s+as\s+\w+|\w+)\s+from\s+"([^"]+)";?/.exec(line);
    if (im) {
      const target = im[1].replace(/^(\.\.?\/)+/, "");
      if (!VIEWER_SOURCES.includes(target)) throw new Error(`${name} imports ${im[1]}, which is not one of the viewer's sources`);
      continue;
    }
    if (/^import\b|^export\s*\{|^export\s+default\b|^export\s+\*/.test(line)) throw new Error(`${name}: "${line.slice(0, 40)}" is not a form this bundle takes`);
    out.push(line.replace(/^export\s+(const|let|var|function|async function|class)\b/, "$1"));
  }
  return out.join("\n");
}

/** The bundle's text from the sources [{ name, text, sha256 }] in VIEWER_SOURCES' order: a header naming each source
    and its hash, then each module as a plain script in strict mode. */
export function bundleViewer(sources) {
  const names = sources.map((s) => s.name);
  if (names.join(",") !== VIEWER_SOURCES.join(",")) throw new Error(`the sources are ${names.join(", ")}; the bundle takes ${VIEWER_SOURCES.join(", ")} in that order`);
  const head = `// diff-ref-struct Map viewer, one classic script (Plots' step 18, L409; PL38). Generated by app/ui/tools/bundle-viewer.mjs: do not edit. Sources (app/ui/): ${sources.map((s) => `${s.name} sha256 ${s.sha256}`).join("; ")}.\n"use strict";\n`;
  return head + sources.map((s) => `\n// ---- ${s.name} ----\n${plainScript(s.name, s.text)}\n`).join("");
}

/** SOURCES.txt: one line per source, its path and its sha256. */
export function sourcesText(sources) {
  return sources.map((s) => `${s.name} ${s.sha256}\n`).join("");
}
